-- Placeholders like {{ run_id }} are filled in by the ELT DAG at run time.
-- Adds one f_<check> column per rule, plus dq_status, failure_reason, warning_reason
CREATE OR REPLACE TABLE stg_products_flagged AS
SELECT *,
  CASE WHEN "f_product_id_not_null" OR "f_product_id_unique" THEN 'FAIL' WHEN "f_category_present" OR "f_mrp_positive" OR "f_cost_price_positive" OR "f_cost_price_not_above_mrp" THEN 'WARN' ELSE 'PASS' END AS dq_status,
  NULLIF(concat_ws('; ', CASE WHEN "f_product_id_not_null" THEN 'product_id_not_null' END, CASE WHEN "f_product_id_unique" THEN 'product_id_unique' END), '') AS failure_reason,
  NULLIF(concat_ws('; ', CASE WHEN "f_category_present" THEN 'category_present' END, CASE WHEN "f_mrp_positive" THEN 'mrp_positive' END, CASE WHEN "f_cost_price_positive" THEN 'cost_price_positive' END, CASE WHEN "f_cost_price_not_above_mrp" THEN 'cost_price_not_above_mrp' END), '') AS warning_reason
FROM (
  SELECT t.*,
    COALESCE((t.product_id IS NULL), FALSE) AS "f_product_id_not_null",
    COALESCE((t.category IS NULL), FALSE) AS "f_category_present",
    COALESCE((t.product_id IS NOT NULL AND row_number() OVER (PARTITION BY t.product_id ORDER BY CASE WHEN t.product_name LIKE '%(old)' THEN 1 ELSE 0 END, t._row) > 1), FALSE) AS "f_product_id_unique",
    COALESCE((t.mrp IS NULL OR t.mrp <= 0), FALSE) AS "f_mrp_positive",
    COALESCE((t.cost_price IS NULL OR t.cost_price <= 0), FALSE) AS "f_cost_price_positive",
    COALESCE((t.cost_price IS NOT NULL AND t.mrp > 0 AND t.cost_price > t.mrp), FALSE) AS "f_cost_price_not_above_mrp"
  FROM stg_products_std t
) AS flagged;
